 {id:'07',lecture:21,title:'ASM charts with Mealy and Moore detectors',short:'ASM charts',reading:'Chapter 8 §§8.4–8.6; Chapter 7 §7.4',clo:'FSM representation and the bridge to CLO6',time:'75 min + extension',slides:'Slides_Final_2026/L21_ASM_Mealy_and_Moore_Sequence_Detectors.pptx',outcomes:['Convert Mealy and Moore 101 state diagrams into ASM blocks','Place conditional and state outputs correctly','Trace input preparation, clock edges and overlapping detections','Describe a register controller using an ASM chart']},
 {id:'08',lecture:22,title:'ROM implementation of digital circuits',short:'ROM design',reading:'Chapter 5 §5.6 and Chapter 8 §8.3',clo:'CLO6: ROM, PLA and PAL',time:'75 min + worked extensions',slides:'Slides_Final_2026/L22_ROM_Combinational_and_Sequential_Design.pptx',outcomes:['Determine ROM address width, word width and capacity','Program complete truth tables and next-state tables','Implement counters, registers, shifters, generators and detectors with ROM plus storage','Explain unused-state recovery and ripple-reset timing']},
 {id:'09',lecture:23,title:'PLA and PAL design across the course',short:'PLA and PAL integration',reading:'Chapter 5 §5.6 and Chapter 8 §8.3',clo:'CLO6: ROM, PLA and PAL',time:'75 min + design workshop',slides:'Slides_Final_2026/L23_PLA_PAL_Integrated_Digital_Design.pptx',outcomes:['Translate SOP equations into PLA programming tables','Allocate PAL product terms to output groups','Implement familiar sequential circuits using programmed logic and state storage','Verify function, initialization, physical fit and timing']}
