 const step=()=>{if(ix<frames.length-1){ix++;draw();}};
 $('.advance',root).onclick=()=>{stop();step();};$('.previous',root).onclick=()=>{stop();ix=Math.max(0,ix-1);draw();};$('.reset',root).onclick=()=>{stop();ix=0;draw();};$('.play',root).onclick=()=>{if(timer){stop();return;}if(ix===frames.length-1)ix=0;$('.play',root).textContent='Pause';timer=setInterval(step,1100);};
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',stop,{once:true});draw();return {stop,draw,getFrame:()=>frames[ix]};
