 let b='';[0,1,2].forEach(i=>{const x=65+i*340;b+=box(x,65,230,105,`JK FF${i}\nJ=K=1\nQ${i}=${(f.q>>i)&1}`,'logic-box'+(((f.q>>i)&1)?' hot':''));if(i<2)b+=wire(`M${x+230} 117 H${x+340}`)+rr(x+235,100,`Q${i} → CLK`,'small-label');});b+=wire('M25 117 H65')+rr(16,91,'CLK ↓','signal-label')+box(375,255,370,65,`Terminal decoder: CLR_n=${f.clear}`,!f.clear?'logic-box hot':'logic-box')+wire('M745 287 H1080 V35 H180 V65',!f.clear)+wire('M520 35 V65',!f.clear)+wire('M860 35 V65',!f.clear)+wire('M520 170 V255')+wire('M860 170 V220 H690 V255')+rr(350,21,'common asynchronous clear to all stages','small-label');
